import sys

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    rows = [input().strip() for _ in range(n)]

    cnt = [0] * m
    for s in rows:
        for j, ch in enumerate(s):
            if ch == '1':
                cnt[j] += 1

    for s in rows:
        ok = True
        for j, ch in enumerate(s):
            if ch == '1' and cnt[j] == 1:
                ok = False
                break
        if ok:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    main()
